// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "I have a my apps linux container running at 192.168.100.125. could you remake the app using tanstack and have the state of it persist with a local sqlite database. also use React for the UI with components from: https://www.reactbits.dev/. after you are done could you deploy it onto the container."
// Changes: LL tab – grammar editor, checks, LL table, Empty/First/Follow/Predict and LL parse simulation.

import { useNavigate } from '@tanstack/react-router'
import { useMemo } from 'react'
import { analyzeDefinition } from '#/lib/definition'
import { fmtSet, llProblems, ruleText, type LLAnalysis } from '#/lib/grammar'
import type { ProjectData } from '#/lib/project'
import { Button, CollapsiblePanel, Help, ListTable, Panel, Problems, ResultLine, Segmented, cx, headCell, tableCell } from './ui'
import { LLSimulation } from './LLSimulation'
import { SplitLayout } from './SplitLayout'

type Update = (fn: (d: ProjectData) => ProjectData) => void
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
// Changes: LL tab modes – sim (simulation) and view (viewer).
export type LLMode = 'sim' | 'view'

export function LLTab({
  data,
  update,
  analysis,
  errors,
  mode,
  onMode,
}: {
  data: ProjectData
  update: Update
  analysis: LLAnalysis | null
  errors: string[]
  mode: LLMode
  onMode: (mode: LLMode) => void
}) {
  const a = analysis
  const problems = useMemo(() => llProblems(errors, a), [errors, a])
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "LL by teraz mala pouzivat gramatiku, ktoru si vytvorim v tabulke definicia"
  // Changes: Count errors of the definition so the LL tab can point to them.
  const navigate = useNavigate()
  const defErrors = useMemo(() => analyzeDefinition(data.def, a, errors).problems.filter((p) => p.level === 'bad').length, [data.def, a, errors])

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
  // Changes: Two modes. Simulácia – step-by-step simulation with the reduced LL table (own layout).
  //          Prehliadač – grammar and rules on the left; LL table, checks and Empty/First/Follow/Predict on the right.
  const modeSwitch = (
    <div className="mb-4 flex shrink-0 flex-wrap items-center gap-3">
      <Segmented
        label="Režim LL záložky"
        value={mode}
        onChange={onMode}
        options={[
          { value: 'sim', label: 'Simulácia' },
          { value: 'view', label: 'Prehliadač' },
        ]}
      />
      {defErrors > 0 && (
        <button type="button" onClick={() => void navigate({ to: '.', search: (prev) => ({ ...prev, tab: 'def' }), replace: true })} className="text-xs text-rose-300 hover:underline">
          {defErrors} {defErrors === 1 ? 'chyba' : defErrors < 5 ? 'chyby' : 'chýb'} v Definícii
        </button>
      )}
    </div>
  )

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
  // Changes: Both modes fill the viewport height on wide screens; the mode switch stays on top, the columns scroll.
  const frame = 'lg:flex lg:h-[calc(100dvh-6.5rem)] lg:min-h-[34rem] lg:flex-col lg:[&>*:last-child]:min-h-0 lg:[&>*:last-child]:flex-1'

  if (mode === 'sim') {
    return (
      <div className={frame}>
        {modeSwitch}
        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "also make sure that the simulation input and state is also saved in the DB"
            Changes: Simulation step/speed are read from and written to the project data (autosaved). */}
        <LLSimulation
          a={a}
          input={data.ll.input}
          onInput={(v) => update((d) => ({ ...d, ll: { ...d.ll, input: v } }))}
          state={data.ll.sim}
          onState={(fn) => update((d) => ({ ...d, ll: { ...d.ll, sim: fn(d.ll.sim) } }))}
        />
      </div>
    )
  }

  return (
    <div className={frame}>
      {modeSwitch}
      <SplitLayout id="ll" fill>
        <div className="min-w-0">
          <CollapsiblePanel
            defaultOpen
            title="Gramatika"
            summary={
              <>
                |N| = {a?.N.length ?? 0}, |T| = {a?.T.length ?? 0}, |P| = {a?.rules.length ?? 0}
                {defErrors > 0 && <span className="ml-2 text-rose-300">· {defErrors} {defErrors === 1 ? 'chyba' : defErrors < 5 ? 'chyby' : 'chýb'} v Definícii</span>}
              </>
            }
          >
            <div className="mb-3">
              <Button onClick={() => void navigate({ to: '.', search: (prev) => ({ ...prev, tab: 'def' }), replace: true })}>Upraviť v Definícii</Button>
            </div>
            <dl className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-1.5 font-mono text-[13px]">
              <dt className="text-zinc-500">N =</dt>
              <dd className="break-words text-zinc-200">{a ? fmtSet(a.N) : '∅'}</dd>
              <dt className="text-zinc-500">T =</dt>
              <dd className="break-words text-zinc-200">{a ? fmtSet(a.T) : '∅'}</dd>
              <dt className="text-zinc-500">S =</dt>
              <dd className="text-zinc-200">{a?.N[0] ?? '–'}</dd>
              <dt className="text-zinc-500">|P| =</dt>
              <dd className="text-zinc-200">{a?.rules.length ?? 0}</dd>
            </dl>
            <Help>
              LL analýza používa gramatiku <code>G = (N, T, P, S)</code> zo záložky Definícia: riadky tabuľky sú neterminály z
              N (S prvý), stĺpce terminály z T a <code>$</code>.
            </Help>
            {defErrors > 0 && (
              <ResultLine ok={false}>Definícia má {defErrors} {defErrors === 1 ? 'chybu' : defErrors < 5 ? 'chyby' : 'chýb'} – pozri záložku Definícia.</ResultLine>
            )}
          </CollapsiblePanel>
          {a && (
            <Panel title="Pravidlá">
              <ol className="list-decimal pl-9 font-mono text-[13px] text-zinc-300 marker:text-zinc-500">
                {a.rules.map((r, i) => (
                  <li key={i}>{ruleText(r)}</li>
                ))}
              </ol>
            </Panel>
          )}
        </div>

        <div className="min-w-0">
          {a && (
            <Panel title="LL tabuľka">
              <Help>
                Riadok = neterminál na vrchole zásobníka, stĺpec = vstupný token, bunka = číslo pravidla. Červená bunka =
                konflikt (gramatika nie je LL(1)).
              </Help>
              <div className="mt-3 overflow-x-auto">
                <table className="border-collapse font-mono text-[13px]">
                  <thead>
                    <tr>
                      <th className={headCell} />
                      {a.cols.map((c) => (
                        <th key={c} className={headCell}>
                          {c}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {a.N.map((A) => (
                      <tr key={A}>
                        <th className={cx(headCell, 'text-left')}>{A}</th>
                        {a.cols.map((c) => {
                          const cell = a.table.get(A)!.get(c) ?? []
                          return (
                            <td
                              key={c}
                              title={cell.map((i) => `${i}: ${ruleText(a.rules[i - 1])}`).join('\n')}
                              className={cx(
                                tableCell,
                                cell.length > 1 && 'bg-rose-500/20 font-bold text-rose-200',
                                cell.length === 1 && 'text-indigo-200',
                              )}
                            >
                              {cell.join(', ')}
                            </td>
                          )
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="mt-2 font-mono text-xs text-zinc-500">Terminály: {a.T.join('  ')}</div>
            </Panel>
          )}
          <Panel title="Kontrola">
            <Problems items={problems} />
          </Panel>
          {a && (
            <>
              <Panel title="Množiny Empty, First, Follow">
                <ListTable head={['Neterminál', 'Empty', 'First', 'Follow']}>
                  {a.N.map((n) => (
                    <tr key={n}>
                      <td>{n}</td>
                      <td>{a.empty.has(n) ? '{ ε }' : '∅'}</td>
                      <td>{fmtSet(a.order(a.first.get(n)!))}</td>
                      <td>{fmtSet(a.order(a.follow.get(n)!))}</td>
                    </tr>
                  ))}
                </ListTable>
              </Panel>
              <Panel title="Predict">
                <ListTable head={['#', 'Pravidlo', 'Predict']}>
                  {a.rules.map((r, i) => (
                    <tr key={i}>
                      <td>{i + 1}</td>
                      <td>{ruleText(r)}</td>
                      <td>{fmtSet(a.order(a.predict[i]))}</td>
                    </tr>
                  ))}
                </ListTable>
              </Panel>
            </>
          )}
        </div>
      </SplitLayout>
    </div>
  )
}
